param([Parameter(Mandatory)][string]$ProjectRoot,[Parameter(Mandatory)][string]$BuildRoot)
$ErrorActionPreference='Stop';$root=Join-Path $BuildRoot ('integration/review-prefix-background-'+[guid]::NewGuid().ToString('N'));New-Item -ItemType Directory -Force $root|Out-Null
Add-Type -Path (Join-Path $ProjectRoot tests/PrivateDesktop.cs);$env:HIBERNATION_SESSION_KEY='review-prefix-background';$desktop=$null;$service=$null;$provider=$null;$checks=0
function Check($Value,$Label){if(!$Value){throw "CHECK FAILED: $Label"};$script:checks++;Write-Output "PASS $Label"}
function Await([scriptblock]$Probe,$Label,[int]$Seconds=100){$until=[DateTime]::UtcNow.AddSeconds($Seconds);while([DateTime]::UtcNow-lt$until){if(&$Probe){return};Start-Sleep -Milliseconds 70};throw "TIMEOUT $Label"}
function Api($Path,$Data=$null){$p=@{Uri=$script:origin+$Path;Headers=@{Authorization='Bearer review-prefix-background'};TimeoutSec=12};if($null-ne$Data){$p.Method='Post';$p.ContentType='application/json';$p.Body=[Text.Encoding]::UTF8.GetBytes(($Data|ConvertTo-Json -Depth 65 -Compress))};Invoke-RestMethod @p}
try{
 $providerRoot=Join-Path $root provider;New-Item -ItemType Directory -Force $providerRoot|Out-Null;$provider=Start-Process -FilePath (Join-Path $BuildRoot Hibernation_TestProvider.exe) -ArgumentList ('"'+$providerRoot+'"') -WindowStyle Hidden -PassThru;Await {Test-Path (Join-Path $providerRoot port)} 'provider' 30;$fixture='http://127.0.0.1:'+(Get-Content (Join-Path $providerRoot port))
 $cfg=Get-Content (Join-Path $ProjectRoot config/example.json) -Raw|ConvertFrom-Json -AsHashtable;$cfg.dataRoot=Join-Path $root data;$cfg.characterRoot=Join-Path $ProjectRoot character;$cfg.uiRoot=Join-Path $ProjectRoot ui;$cfg.pluginRoot=Join-Path $BuildRoot plugins;$cfg.frontend.startupAnimation=$false;$cfg.backgroundBudget=@{enabled=$false};$cfg.maxStartsPerHour=1000;$cfg.solitudeIntervalMs=604800000;$cfg.idleBeforeSolitudeMs=86400000;$cfg.contextControl=@{reviewLayout='prefix';backgroundProjection=$true};$cfg.review=@{enabled=$true;profileId='review';maxRewrites=0}
 $cfg.profiles=@($cfg.profiles[0],@{id='actor';label='Actor';protocol='chat-completions';enabled=$true;origin=$fixture;model='fixture-model';supportsJsonObject=$true},@{id='review';label='Review';protocol='chat-completions';enabled=$true;origin=$fixture;model='fixture-reviewer';supportsJsonObject=$true})
 $cfg.plugins=@{widget=@{enabled=$true;skin='dinosaur';animationMode='procedural';roam=$false;autonomousMode=$true;autonomyIdleSeconds=5;autonomyRefillSeconds=30;reactionCacheEnabled=$false;showBubble=$false}}
 $cfg|ConvertTo-Json -Depth 65|Set-Content -LiteralPath (Join-Path $root config.json) -Encoding utf8
 @{nonce='actor';responses=@(@{response=@{version=1;commands=@()}})}|ConvertTo-Json -Depth 40|Set-Content -LiteralPath (Join-Path $providerRoot plan.json) -Encoding utf8
 @{nonce='review';responses=@(@{response=@{decision='approve';reason='ok';guidance=''}})}|ConvertTo-Json -Depth 40|Set-Content -LiteralPath (Join-Path $providerRoot review-plan.json) -Encoding utf8
 $desktop=[PrivateDesktop]::new((Join-Path $BuildRoot hibernation-agent.exe),(Join-Path $root config.json),(Join-Path $root ready.json),$ProjectRoot);$service=$desktop.Child;Await {if($service.HasExited){throw 'Background fixture exited'};Test-Path (Join-Path $root ready.json)} 'backend' 30;$script:origin='http://127.0.0.1:'+((Get-Content (Join-Path $root ready.json) -Raw|ConvertFrom-Json).port);$null=Api '/api/model' @{id='actor'}
 $null=Api '/api/control' @{paused=$false};$null=Api '/api/surfaces/show' @{id='widget'}
 Check ((Api '/api/activities/status').enabled) 'background fixture has an enabled autonomous widget before waiting'
 try{Await {if(Test-Path (Join-Path $providerRoot review-requests.jsonl)){return @(Get-Content (Join-Path $providerRoot review-requests.jsonl)).Count-ge2};$false} 'two independent background reviews'}catch{$d=Api '/api/dashboard';@{runtime=$d.runtime_status;activities=(Api '/api/activities/status');control=(Api '/api/state').control;plugins=(Api '/api/capabilities').plugins}|ConvertTo-Json -Depth 8|Set-Content -LiteralPath (Join-Path $root diagnostic.json) -Encoding utf8;throw}
 $wire=@(Get-Content (Join-Path $providerRoot review-requests.jsonl)|ForEach-Object {$_|ConvertFrom-Json -Depth 85});$one=$wire[0];$two=$wire[1];$prefixCount=$one.messages.Count-1
 Check (($one.messages[0..($prefixCount-1)]|ConvertTo-Json -Depth 85 -Compress)-ceq($two.messages[0..($prefixCount-1)]|ConvertTo-Json -Depth 85 -Compress)) 'background reviewer retains the same actual sent definition prefix'
 Check (@($two.messages|Where-Object {$_.content.Contains('"review_snapshot"')}).Count-eq1) 'background review does not replay previous candidate snapshots'
 $snapshot=$two.messages[-1].content|ConvertFrom-Json -Depth 85;Check ($snapshot.review_snapshot.data.context.PSObject.Properties.Name-contains'state'-and$snapshot.review_snapshot.data.context.PSObject.Properties.Name-contains'available_commands') 'latest full planning state and executable commands remain present'
 $actors=@(Get-Content (Join-Path $providerRoot requests.jsonl)|ForEach-Object {$_|ConvertFrom-Json -Depth 85});Check ($actors[-1].messages.Count-gt$actors[0].messages.Count) 'ordinary planning connection also uses configured append-only snapshots'
 $null=Api '/api/shutdown' @{};Check ($service.WaitForExit(10000)) 'background fixture shuts down cleanly';@{passed=$true;checks=$checks;paid_requests=0}|ConvertTo-Json|Set-Content -LiteralPath (Join-Path $root acceptance.json) -Encoding utf8
}finally{if($service-and!$service.HasExited){Stop-Process -Id $service.Id -Force};if($desktop){$desktop.Dispose()};if($provider-and!$provider.HasExited){Stop-Process -Id $provider.Id -Force}}
